// Agrupa todo por clinica y arma el email. Devuelve UN item por clinica.
const soloFilas = arr => arr.map(i => i.json || {}).filter(r => r && r.id);

const clinicas    = soloFilas($('Cargar clinicas').all());
const citas       = soloFilas($('Cargar citas').all());
const leads       = soloFilas($('Cargar leads').all());
const derivaciones = soloFilas($('Cargar derivaciones pendientes').all());

if (!clinicas.length) return [];

const esc = v => (v === null || v === undefined ? '' : v.toString())
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const diaISO = (fecha, tz) => {
  const p = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(fecha);
  const g = t => p.find(x => x.type === t).value;
  return g('year') + '-' + g('month') + '-' + g('day');
};
const sumarDias = (iso, n) => {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
};
const aES = iso => (iso || '').split('-').reverse().join('/');
const normFecha = f => {
  if (!f) return '';
  const v = f.toString().trim();
  const iso = v.match(/^(\d{4})-(\d{2})-(\d{2})/);
  return iso ? iso[1] + '-' + iso[2] + '-' + iso[3] : v;
};

return clinicas.map(clinica => {
  const tz = clinica.zona_horaria || 'Europe/Madrid';
  const hoy = diaISO(new Date(), tz);
  const haceUnaSemana = sumarDias(hoy, -7);
  const dentroDeUnaSemana = sumarDias(hoy, 7);

  const mias = arr => arr.filter(r => r.clinica_id === clinica.id);

  const citasC = mias(citas);
  const leadsC = mias(leads);
  const derivC = mias(derivaciones);

  const semanaPasada = citasC.filter(c => {
    const f = normFecha(c.fecha);
    return f >= haceUnaSemana && f < hoy;
  });
  const atendidas = semanaPasada.filter(c => (c.estado || '') === 'confirmada');
  const canceladas = semanaPasada.filter(c => (c.estado || '') === 'cancelada');

  const proximas = citasC
    .filter(c => {
      const f = normFecha(c.fecha);
      return (c.estado || '') === 'confirmada' && f >= hoy && f <= dentroDeUnaSemana;
    })
    .sort((a, b) => (normFecha(a.fecha) + (a.hora || '')).localeCompare(normFecha(b.fecha) + (b.hora || '')));

  const valoradas = citasC.filter(c => Number.isFinite(Number(c.valoracion)) && Number(c.valoracion) >= 1);
  const media = valoradas.length
    ? (valoradas.reduce((s, c) => s + Number(c.valoracion), 0) / valoradas.length).toFixed(1)
    : null;

  const fila = (etiqueta, valor, color) =>
    '<tr><td style="padding:10px 8px;border-bottom:1px solid #eee">' + esc(etiqueta) + '</td>' +
    '<td style="padding:10px 8px;border-bottom:1px solid #eee;text-align:right;font-weight:bold;color:' + (color || '#222') + '">' + esc(valor) + '</td></tr>';

  const bloqueLista = (titulo, items, vacio) => {
    if (!items.length) return '<p style="color:#888;margin:6px 0 18px">' + esc(vacio) + '</p>';
    return '<ul style="margin:6px 0 18px;padding-left:18px;color:#333">' +
      items.map(t => '<li style="margin-bottom:4px">' + t + '</li>').join('') + '</ul>';
  };

  const listaLeads = leadsC.slice(0, 15).map(l =>
    '<b>' + esc(l.nombre || 'Sin nombre') + '</b> — ' + esc(l.tratamiento_interes || 'consulta general') +
    ' <span style="color:#888">(' + esc(l.telefono || '') + ')</span>');

  const listaDeriv = derivC.slice(0, 15).map(d =>
    '<b>' + esc(d.nombre || 'Sin nombre') + '</b> — ' + esc(d.motivo || '') +
    ' <span style="color:#888">(' + esc(d.telefono || '') + ', ' + esc(d.fecha_hora || '') + ')</span>');

  const listaProximas = proximas.slice(0, 20).map(c =>
    esc(aES(normFecha(c.fecha))) + ' ' + esc(c.hora || '') + ' — <b>' + esc(c.nombre || '') + '</b> (' + esc(c.tratamiento || '') + ')');

  const listaValoraciones = valoradas.slice(0, 10).map(c =>
    '★'.repeat(Number(c.valoracion)) + ' <b>' + esc(c.nombre || '') + '</b>' +
    (c.comentario_valoracion ? ' — ' + esc(c.comentario_valoracion) : ''));

  const html = [
    '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;color:#222">',
    '<h2 style="color:#1a7f5a;border-bottom:3px solid #1a7f5a;padding-bottom:10px;margin-bottom:4px">Resumen semanal</h2>',
    '<p style="color:#666;margin-top:0">' + esc(clinica.nombre) + ' &middot; del ' + esc(aES(haceUnaSemana)) + ' al ' + esc(aES(hoy)) + '</p>',

    '<table style="width:100%;border-collapse:collapse;margin:18px 0">',
    fila('Citas atendidas la semana pasada', atendidas.length, '#1a7f5a'),
    fila('Citas canceladas', canceladas.length, canceladas.length ? '#d9534f' : '#222'),
    fila('Citas para los proximos 7 dias', proximas.length, '#1a7f5a'),
    fila('Nuevos interesados (leads)', leadsC.length, leadsC.length ? '#8a4b16' : '#222'),
    fila('Valoraciones recibidas', valoradas.length + (media ? ' (media ' + media + '/5)' : ''), '#1a7f5a'),
    fila('Consultas pendientes de atender', derivC.length, derivC.length ? '#d9534f' : '#222'),
    '</table>',

    derivC.length ? '<h3 style="color:#d9534f;margin-bottom:2px">⚠️ Consultas que esperan respuesta</h3>' : '',
    derivC.length ? bloqueLista('', listaDeriv, '') : '',

    '<h3 style="color:#8a4b16;margin-bottom:2px">Nuevos interesados</h3>',
    bloqueLista('', listaLeads, 'Ningun interesado nuevo esta semana.'),

    '<h3 style="color:#1a7f5a;margin-bottom:2px">Proximas citas</h3>',
    bloqueLista('', listaProximas, 'No hay citas en los proximos 7 dias.'),

    '<h3 style="color:#1a7f5a;margin-bottom:2px">Valoraciones</h3>',
    bloqueLista('', listaValoraciones, 'Sin valoraciones nuevas.'),

    '<p style="color:#999;font-size:12px;margin-top:24px;border-top:1px solid #eee;padding-top:12px">',
    'Resumen generado automaticamente. Los listados muestran como maximo los primeros resultados.',
    '</p>',
    '</div>'
  ].join('');

  return {
    json: {
      clinica_id: clinica.id,
      clinica_nombre: clinica.nombre,
      email_avisos: clinica.email_avisos,
      email_subject: 'Resumen semanal ' + clinica.nombre + ' (' + aES(haceUnaSemana) + ' - ' + aES(hoy) + ')',
      email_html: html,
      total_citas: atendidas.length,
      total_leads: leadsC.length,
      total_derivaciones: derivC.length
    }
  };
}).filter(item => !!item.json.email_avisos);
